DBDATABUILD_TEST_MSSQL2025 <- DBKIT_TEST_MSSQL2025
DBDATABUILD_TEST_ORACLE    <- DBKIT_TEST_ORACLE_KV
DBDATABUILD_TEST_SPARK     <- DBKIT_TEST_SPARK
DBDATABUILD_TEST_BIGQUERY  <- DBKIT_TEST_BIGQUERY
DBDATABUILD_TEST_FLIGHT     <- DBKIT_TEST_FLIGHT
DBDATABUILD_TEST_FLIGHT_TLS <- DBKIT_TEST_FLIGHT_TLS
DBDATABUILD_TEST_FLIGHT_CA  <- DBKIT_TEST_FLIGHT_TLS_CA
